SELECT class_id, name, status, length(markdown) AS bytes, instr(markdown, char(13)) > 0 AS has_cr
  FROM imported_classes WHERE class_id = 'nb-hunter';
SELECT count(*) AS stub_gear FROM gear WHERE slug IN ('darkblade-scimitar-nb');

